let lang='en';try{lang=localStorage.getItem('bint-language')||'en'}catch{}if(!words[lang])lang='en';
let events=[],categories=[],view='schedule',activeEvent=null;
const $=s=>document.querySelector(s),t=k=>words[lang][k]||k,locale=()=>({en:'en-GB',th:'th-TH-u-ca-gregory',zh:'zh-CN'}[lang]);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr=x=>typeof x==='string'?x:(x?.[lang]||x?.en||'');
const link=x=>{try{const u=new URL(x,location.href);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}};
const cat=e=>categories.find(c=>c.id===e.category);
const countryName=c=>c?new Intl.DisplayNames([locale()],{type:'region'}).of(c):t('unknownCountry');
const selected=()=>Object.fromEntries(['year','month','category','country'].map(k=>[k,$('#'+k).value]));
const active=e=>!['cancelled','postponed'].includes(e.status)&&!isPast(e);
const sort=(a,b)=>a.date.localeCompare(b.date)||(a.start_time||'99').localeCompare(b.start_time||'99');
function displayedDate(e){return $('#local').checked&&e.start_time&&e.timezone?dateInZone(zonedDate(e.date,e.start_time,e.timezone),Intl.DateTimeFormat().resolvedOptions().timeZone):e.date}
function dateText(date,options={day:'numeric',month:'short',year:'numeric'}){return new Intl.DateTimeFormat(locale(),{...options,timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'))}
function range(e){const d=displayedDate(e);return dateText(d)+(e.end_date&&e.end_date!==e.date?' – '+dateText(e.end_date):'')}
function timeText(e){if(!e.start_time)return t('timeTbc');if(!e.timezone)return e.start_time+' · '+t('unknownZone');const zone=$('#local').checked?Intl.DateTimeFormat().resolvedOptions().timeZone:e.timezone;const fmt=new Intl.DateTimeFormat(locale(),{timeZone:zone,hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZoneName:'short'});return fmt.format(zonedDate(e.date,e.start_time,e.timezone))+(e.end_time?' – '+fmt.format(zonedDate(e.end_date||e.date,e.end_time,e.timezone)):'')}
function access(e){return t(e.access==='tbc'?'attendanceTbc':e.access||'attendanceTbc')}
function state(e){if(['cancelled','postponed'].includes(e.status))return t(e.status);if(isPast(e))return t('completed');if(e.date<=dateInZone(new Date(),e.timezone||'UTC'))return t('ongoing');return t(e.status||'confirmed')}
function calendar(e){const extra=!e.start_time?t('allDayNote'):!e.end_time?t('endNote'):'';return calendarURL({...e,calendarLocation:tr(e.venue)},tr(e.title),[tr(e.notes),access(e),extra,'#bintsireethorn',t('source')+' '+e.source].filter(Boolean).join('\n\n'))}
function options(id,values,allLabel){const s=$('#'+id),previous=s.value;s.innerHTML=`<option value="all">${esc(t(allLabel))}</option>`+values.map(([v,n])=>`<option value="${esc(v)}">${esc(n)}</option>`).join('');if([...s.options].some(o=>o.value===previous))s.value=previous}
function updateFilters(){options('year',[...new Set(events.map(e=>e.date.slice(0,4)))].sort().map(y=>[y,y]),'all');options('month',Array.from({length:12},(_,i)=>[String(i+1).padStart(2,'0'),dateText('2026-'+String(i+1).padStart(2,'0')+'-01',{month:'long'})]),'allMonths');options('category',categories.map(c=>[c.id,tr(c.label)]),'allCategories');options('country',[...new Set(events.map(e=>e.country||'tbc'))].sort().map(c=>[c,c==='tbc'?t('unknownCountry'):countryName(c)]),'allCountries')}
function translate(){document.documentElement.lang=lang==='zh'?'zh-Hans':lang;document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.lang===lang));$('.close').ariaLabel=t('close');updateFilters();render();if(activeEvent)renderDetails(activeEvent)}
const icons={clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[k]}</svg>`;
function card(e){
  const d=displayedDate(e),url=calendar(e),past=isPast(e)&&!['cancelled','postponed'].includes(e.status),colour=/^#[a-f0-9]{6}$/i.test(cat(e)?.colour)?cat(e).colour:'#a82b62';
  const badgeKey=past?null:['tentative','details_tbc','cancelled','postponed'].includes(e.status)?e.status:state(e)===t('ongoing')?'ongoing':'upcoming';
  return `<article class="event-card ${past?'is-past':active(e)?'is-upcoming':''} ${e.status==='cancelled'?'cancelled':''}" data-date="${esc(e.date)}" style="--accent:${colour}">
    <div class="dateblock"><span class="day">${new Intl.DateTimeFormat(locale(),{day:'numeric',timeZone:'UTC'}).formatToParts(new Date(d+'T12:00:00Z')).find(part=>part.type==='day').value}</span><span class="month-short">${dateText(d,{month:'short'})}</span><span class="weekday">${dateText(d,{weekday:'short'})}</span></div>
    <div class="event-main"><div class="event-title-row"><h3 class="event-title"><button data-event="${esc(e.id)}">${esc(tr(e.title))}</button></h3>${badgeKey?`<span class="status-badge ${past?'done':'gold'}">${esc(t(badgeKey))}</span>`:''}</div>
    <div class="meta"><span>${icon('clock')}${esc(timeText(e))}${e.end_date?' · '+esc(range(e)):''}</span><span>${icon('pin')}${esc(tr(e.venue))}${e.country?' · '+esc(countryName(e.country)):''}</span></div>
    <div class="badges"><span class="badge"><i></i>${esc(tr(cat(e)?.label)||e.category)}</span><span class="badge neutral">${esc(access(e))}</span></div>
    <div class="card-actions">${url?`<a class="calendar-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${icon('calendar')}${esc(t('calendar').replace(/^\+ /,''))}</a>`:''}<button class="details-button" data-event="${esc(e.id)}">${esc(t('details'))}${icon('right')}</button></div></div></article>`;
}
function monthKeys(){return [...new Set(events.map(e=>e.date.slice(0,7)))].sort()}
function monthNav(){const f=selected();if(f.month==='all'||f.year==='all')return '';const key=f.year+'-'+f.month,keys=monthKeys(),before=keys.filter(k=>k<key).at(-1),after=keys.find(k=>k>key);return `<nav class="month-nav" aria-label="${esc(t('monthCount'))}"><button data-month="${before||''}" ${before?'':'disabled'} aria-label="${esc(t('previousMonth'))}">${icon('left')}</button><div><p>${esc(t('monthCount'))}</p><h2>${esc(dateText(key+'-01',{month:'long',year:'numeric'}))}</h2></div><button data-month="${after||''}" ${after?'':'disabled'} aria-label="${esc(t('nextMonth'))}">${icon('right')}</button></nav>`}
function renderSchedule(list){
  const groups=new Map();
  for(const e of [...list].sort(sort)){const key=e.date.slice(0,7);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(e)}
  const single=selected().month!=='all'&&selected().year!=='all';
  $('#schedule').innerHTML=monthNav()+[...groups].map(([month,entries])=>`<section class="month-group" aria-label="${esc(dateText(month+'-01',{month:'long',year:'numeric'}))}"><div class="month-header">${single?`<span class="order-note">${esc(t('chronological'))}</span>`:`<h2>${esc(dateText(month+'-01',{month:'long',year:'numeric'}))}</h2>`}<span class="count">${entries.length} ${esc(t('events'))}</span></div><div class="event-list">${entries.map(card).join('')}</div></section>`).join('')+(!list.length?`<div class="empty"><h2>${esc(t('empty'))}</h2><p>${esc(t('emptyHint'))}</p><button class="reset" data-reset>${esc(t('reset'))}</button></div>`:'');
}
function renderDashboard(list){const up=list.filter(active).sort(sort),past=list.filter(e=>!['cancelled','postponed'].includes(e.status)&&isPast(e)),countries=new Set(list.map(e=>e.country).filter(Boolean));const stats=[['total',list.length,'filtered'],['upcoming',up.length,'filtered'],['completed',past.length,'filtered'],['countries',countries.size,'knownOnly']];const mix=categories.map(c=>({c,count:list.filter(e=>e.category===c.id).length})).sort((a,b)=>b.count-a.count);const selection=selected(),annual=filteredEvents(events,{...selection,month:'all'}),years=selection.year==='all'?[...new Set(events.map(e=>e.date.slice(0,4)))].sort():[selection.year];const months=years.flatMap(y=>Array.from({length:12},(_,i)=>{const m=y+'-'+String(i+1).padStart(2,'0');return {m,count:annual.filter(e=>e.date.startsWith(m)).length}}));const max=Math.max(1,...months.map(m=>m.count));$('#dashboard').innerHTML=`<div class="section-heading"><h2>${esc(t('dashboard'))}</h2></div><div class="stats">${stats.map(([label,n,note])=>`<article class="stat"><label>${esc(t(label))}</label><strong>${n}</strong><small>${esc(t(note))}</small></article>`).join('')}</div><div class="dashboard-grid"><article class="panel"><h3>${esc(t('mix'))}</h3>${mix.map(({c,count})=>`<div class="bar-row"><div class="bar-label"><span>${esc(tr(c.label))}</span><span>${count} · ${list.length?Math.round(count/list.length*100):0}%</span></div><div class="bar-track"><div class="bar-fill" style="width:${list.length?count/list.length*100:0}%"></div></div></div>`).join('')}</article><article class="panel"><h3>${esc(t('activity'))}</h3><p class="chart-year">${years.map(esc).join(' · ')}</p><div class="monthly">${months.map(({m,count})=>`<div class="month-column"><span>${count}</span><div class="month-bar" style="height:${count/max*145}px"></div><span>${esc(dateText(m+'-01',{month:'short'}))}</span></div>`).join('')||`<p>${esc(t('empty'))}</p>`}</div><p class="chart-note">${esc(t('chartNote'))}</p></article></div><article class="panel dashboard-bottom"><h3>${esc(t('nextEvents'))}</h3>${up.slice(0,5).map(e=>`<div class="upcoming-row"><time>${esc(dateText(e.date,{day:'numeric',month:'short'}))}</time><button data-event="${esc(e.id)}">${esc(tr(e.title))}</button><span class="badge neutral">${esc(access(e))}</span></div>`).join('')||`<p>${esc(t('noneUpcoming'))}</p>`}</article>`}
function render(){if(!events.length)return;const list=filteredEvents(events,selected());$('#zone-label').textContent=$('#local').checked?Intl.DateTimeFormat().resolvedOptions().timeZone:t('eventTime');renderSchedule(list);renderDashboard(list);$('#schedule-view').hidden=view!=='schedule';$('#dashboard-view').hidden=view!=='dashboard';document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-pressed',b.dataset.view===view)})}
function reset(){['year','month','category','country'].forEach(k=>$('#'+k).value='all');render()}
function renderDetails(e){const url=calendar(e);const line=(label,value)=>`<p class="detail-line"><strong>${esc(t(label))}</strong>${esc(value)}</p>`;$('#detail-content').innerHTML=`<div class="badges"><span class="badge">${esc(tr(cat(e)?.label))}</span><span class="badge gold">${esc(state(e))}</span></div><h2 id="detail-title">${esc(tr(e.title))}</h2>${line('date',range(e))}${line('time',timeText(e))}${line('timezone',e.timezone||t('tbc'))}${line('venue',tr(e.venue))}${line('country',countryName(e.country))}${line('access',access(e))}${tr(e.notes)?`<p class="detail-notes">${esc(tr(e.notes))}</p>`:''}${(!e.start_time||!e.end_time)?`<p class="chart-note">${esc(t(!e.start_time?'allDayNote':'endNote'))}</p>`:''}<div class="detail-links">${url?`<a class="primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(t('calendar'))}</a>`:''}<a href="${link(e.source)}" target="_blank" rel="noopener noreferrer">${esc(t('sourceLink'))}</a></div>${e.source_poster?`<details class="poster"><summary>${esc(t('poster'))}</summary>${(e.source_posters||[e.source_poster]).map(src=>`<img src="${link(src)}" alt="${esc(t('poster'))}" loading="lazy">`).join('')}</details>`:''}`}
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.month){$('#year').value=b.dataset.month.slice(0,4);$('#month').value=b.dataset.month.slice(5,7);render()}if(b.dataset.lang){lang=b.dataset.lang;try{localStorage.setItem('bint-language',lang)}catch{}translate()}if(b.dataset.view){view=b.dataset.view;render()}if(b.dataset.event){activeEvent=events.find(e=>e.id===b.dataset.event);renderDetails(activeEvent);$('#details').showModal()}if(b.hasAttribute('data-reset'))reset()});
$('.close').addEventListener('click',()=>$('#details').close());$('#details').addEventListener('close',()=>activeEvent=null);$('#details').addEventListener('click',e=>{if(e.target===$('#details')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
['year','month','category','country','local'].forEach(k=>$('#'+k).addEventListener('change',render));$('#reset').addEventListener('click',reset);
translate();
try{const responses=await Promise.all(['data/events.json','data/categories.json'].map(p=>fetch(p,{cache:'no-cache'})));if(responses.some(r=>!r.ok))throw Error('Data unavailable');[events,categories]=await Promise.all(responses.map(r=>r.json()));events.sort(sort);updateFilters();const now=dateInZone(new Date(),'Asia/Bangkok');const initial=events.some(e=>e.date.startsWith(now.slice(0,7)))?now.slice(0,7):events.at(-1)?.date.slice(0,7);if(initial){$('#year').value=initial.slice(0,4);$('#month').value=initial.slice(5,7)}render()}catch(error){$('#schedule').innerHTML=`<p class="empty">${esc(t('loadError'))}</p>`;console.error(error)}
setInterval(render,60000);

if(document.modelContext?.registerTool){
  const lifecycle=new AbortController();
  Promise.resolve(document.modelContext.registerTool({
    name:'filter_bint_schedule',
    description:'Set the visible schedule filters and return matching published events. Does not edit events or save calendar entries.',
    inputSchema:{type:'object',properties:{year:{type:'string'},month:{type:'string'},category:{type:'string'},country:{type:'string'}},additionalProperties:false},
    annotations:{readOnlyHint:false,untrustedContentHint:true},
    execute(input){
      if(!input||typeof input!=='object')throw new Error('Filter object required');
      for(const [key,value] of Object.entries(input)){
        if(!['year','month','category','country'].includes(key)||typeof value!=='string'||![...$('#'+key).options].some(o=>o.value===value))throw new Error('Invalid filter');
      }
      for(const [key,value] of Object.entries(input))$('#'+key).value=value;
      view='schedule';render();
      return {events:filteredEvents(events,selected()).map(e=>({id:e.id,title:tr(e.title),date:e.date,time:e.start_time,timezone:e.timezone}))};
    }
  },{signal:lifecycle.signal})).catch(()=>{});
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
